def enlazar_cambios_hechos(apps, schema_editor):
    """
    Enlaza los cambios de asesor que ya se hicieron antes de llevar la cadena:
    en un mismo punto, el que empieza justo el día después de que otro
    termina es quien lo reemplazó.
    """
