    cerrados = AsesorApple.objects.filter(hasta__isnull=False)
    for anterior in cerrados:
        siguiente = (
            AsesorApple.objects.filter(
                id_punto_venta_id=anterior.id_punto_venta_id,
                desde=anterior.hasta + timedelta(days=1),
                reemplaza__isnull=True,
            )
            .exclude(pk=anterior.pk)
            .first()
        )
        if siguiente and not AsesorApple.objects.filter(reemplaza=anterior).exists():
            siguiente.reemplaza = anterior
            siguiente.save(update_fields=['reemplaza'])


